fn meshgrid(x: Vec<f32>, y: Vec<f32>) -> (Vec<Vec<f32>>, Vec<Vec<f32>>) {
    let cols = x.len();
    let rows = y.len();

    // Prepare the output matrices with the correct sizes.
    let mut grid_x = Vec::with_capacity(rows);
    let mut grid_y = Vec::with_capacity(rows);

    // For each element in y, we create one row in each matrix.
    for &y_val in &y {
        // In grid_x, each row is just a clone of the entire x vector.
        grid_x.push(x.clone());

        // In grid_y, each row is a vector filled with the current y_val, repeated `cols` times.
        grid_y.push(vec![y_val; cols]);
    }

    (grid_x, grid_y)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_meshgrid_basic() {
        let x = vec![1.0, 2.0, 3.0];
        let y = vec![4.0, 5.0];
        let (gx, gy) = meshgrid(x, y);

        // grid_x should be
        // [[1.0, 2.0, 3.0],
        //  [1.0, 2.0, 3.0]]
        assert_eq!(gx.len(), 2);
        assert_eq!(gx[0], vec![1.0, 2.0, 3.0]);
        assert_eq!(gx[1], vec![1.0, 2.0, 3.0]);

        // grid_y should be
        // [[4.0, 4.0, 4.0],
        //  [5.0, 5.0, 5.0]]
        assert_eq!(gy.len(), 2);
        assert_eq!(gy[0], vec![4.0, 4.0, 4.0]);
        assert_eq!(gy[1], vec![5.0, 5.0, 5.0]);
    }
}